style.css:
@-moz-document domain("open.spotify.com") {
/* Main background */
  body, #main, .Root__top-container, .Root__now-playing-bar-container {
    background-color: #eaf8ff !important; /* very light baby blue */
    color: #1a237e !important; /* dark blue text for readability */
  }

  /* Sidebar */
  nav[aria-label="Main"], .Root__nav-bar {
    background-color: #f8f8f2 !important; /* off-white sidebar */
  }

  /* Cards & panels */
  div[role="main"], .Type__Container-sc-1j7k0u9-0 {
    background-color: #fdfdf9 !important; /* off-white with slight blue tint */
    color: #1a237e !important;
  }

  /* Buttons and interactive elements */
  button, a, span, p, h1, h2, h3, h4, h5, h6 {
    color: #1a237e !important;
  }

  button:hover {
    background-color: #b3e5fc !important; /* light blue hover */
  }

  /* Remove dark overlays */
  [class*="Overlay"], [class*="Background"] {
    background-color: transparent !important;
  }

  /* Album images/cards stand out */
  img {
    opacity: 1 !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #b3e5fc;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-track {
    background-color: #fdfdf9;
  }
}
